"""Real creation/StateBlock API bodies and response macros; COM/transport adapters."""
import argparse
from pathlib import Path
from generate_buffer_contract_test import method,ROOT


def generate(source, output):
    src=source/'bridge/src'
    header=(src/'util/util_bridgecommand.h').read_text(encoding='utf-8')
    cpp=(src/'client/d3d9_device.cpp').read_text(encoding='utf-8')
    macros=header[header.index('#define WAIT_FOR_SERVER_RESPONSE'):header.index('struct BridgeReadFailure')]
    parts=['#include "ipc_api_failure_support.h"\n',macros]
    for name in ('CreateVertexBuffer','CreateIndexBuffer','CreateVertexShader','CreatePixelShader','CreateStateBlock','BeginStateBlock','EndStateBlock'):
        start,end=method(cpp,'HRESULT Direct3DDevice9Ex_LSS<EnableSync>::'+name+'(')
        catch=' catch (const BridgeReadFailure&) { return D3DERR_DEVICELOST; }'
        if cpp[end:end+len(catch)]!=catch:raise RuntimeError('Missing actual API failure boundary')
        parts.append('template<bool EnableSync>\n'+cpp[start:end+len(catch)]+'\n')
    parts.append('#include "ipc_api_failure_cases.cpp"\n')
    output.mkdir(parents=True, exist_ok=True)
    (output/'ipc_api.cpp').write_text(''.join(parts),encoding='utf-8')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=ROOT / '.deps/dxvk-remix')
    parser.add_argument('--output', type=Path, default=ROOT / '.deps/ipc-api')
    args = parser.parse_args()
    generate(args.source, args.output)
